def solve(inp):
    i=np.array(inp); H,W=i.shape
    cnt=Counter(i.flat); dom,_=cnt.most_common(1)[0]
    sc=[v for v in cnt if v!=dom and v!=0][0]
    srs=[r for r in range(H) if any(i[r]==sc)]; cs=[c for c in range(W) if any(i[:,c]==sc)]
    r0,r1,c0,c1=min(srs),max(srs),min(cs),max(cs)
